<?php

declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Unit\CustomerPolicy;

use CetechDeliveryEngine\Application\CustomerPolicy\{CartPolicyReceiptService,CustomerPolicyPreparedCheckout};
use CetechDeliveryEngine\Infrastructure\Persistence\CustomerPolicyReceiptStorageException;
use CetechDeliveryEngine\Tests\Support\CustomerPolicy\{CustomerPolicyReceiptTestFixture as F,CustomerPolicyDomainFixture as D,CustomerPolicyReceiptTestTransport as T};
use PHPUnit\Framework\TestCase;

final class CartPolicyReceiptServiceTest extends TestCase {
	private function refuse(callable$fn):void{$caught=false;try{$fn();}catch(\RuntimeException|\InvalidArgumentException){$caught=true;}self::assertTrue($caught,'Unsupported original unexpectedly accepted.');}
	public function test_pdp_views_are_stateless_and_do_not_persist_an_acknowledgement():void{$f=new F();$g=$f->grant('');$o=$f->observation($g);$a=$f->service->present_product($g,$o);$b=$f->service->present_product($g,$o);self::assertMatchesRegularExpression('/\Acp1p\.[0-9a-f]{32}\.[0-9a-f]{64}\z/D',$a);self::assertNotSame($a,$b);self::assertSame([],$f->rows());self::assertStringNotContainsString('policy_uuid',$a);}
	public function test_served_pdp_ticket_rebinds_only_to_actual_same_native_cart_frame():void{$f=new F();$p=$f->grant('');$ticket=$f->service->present_product($p,$f->observation($p));$g=$f->grant();$o=$f->observation($g);self::assertTrue($f->service->accept_after_add($ticket,$g,$o));self::assertCount(1,$f->rows());self::assertTrue($f->service->preflight(['native-key'=>$g],['native-key'=>$o]));}
	public function test_pdp_wrong_quantity_context_and_mac_never_acknowledge():void{foreach([['quantity'=>'2'],['context_digest'=>str_repeat('c',64)],[]]as$i=>$change){$f=new F();$p=$f->grant('');$t=$f->service->present_product($p,$f->observation($p));if(2===$i){$t=substr($t,0,-1).('a'===substr($t,-1)?'b':'a');}$g=$f->grant('native-key',$change);self::assertFalse($f->service->accept_after_add($t,$g,$f->observation($g)));self::assertSame([],$f->rows());}}
	public function test_foreign_session_cannot_replay_a_served_product_ticket():void{$a=new F();$p=$a->grant('');$t=$a->service->present_product($p,$a->observation($p));$b=new F($a->pdo,str_repeat('b',64));$g=$b->grant();self::assertFalse($b->service->accept_after_add($t,$g,$b->observation($g)));self::assertSame([],$b->rows());}
	public function test_cart_display_requires_explicit_review_and_does_not_write():void{$f=new F();$g=$f->grant();$o=$f->observation($g);$v=$f->service->present_line($g,$o);self::assertSame('review_required',$v['status']);self::assertNotNull($v['ticket']);self::assertSame([],$f->rows());self::assertFalse($f->service->preflight(['native-key'=>$g],['native-key'=>$o]));self::assertTrue($f->service->accept_line($v['ticket'],$g,$o));$ready=$f->service->present_line($g,$o);self::assertSame('ready',$ready['status']);self::assertNull($ready['ticket']);}
	public function test_exact_accepted_ticket_replay_is_known_without_a_second_revision():void{$f=new F();$g=$f->grant();$o=$f->observation($g);$v=$f->service->present_line($g,$o);self::assertTrue($f->service->accept_line($v['ticket'],$g,$o));$rows=$f->rows();self::assertTrue($f->service->reconcile_review($v['ticket'],$g));self::assertTrue($f->service->accept_line($v['ticket'],$g,$o));self::assertSame($rows,$f->rows());self::assertSame(0,$f->source_reads);}
	public function test_changed_source_cannot_reuse_a_previously_accepted_receipt():void{$f=new F();[$g,$o]=$f->accepted();$changed=$f->families;$changed['return_policy_v1']=D::capture(content:['summary'=>'A newly published summary'])['record'];$next=$f->observation($g,$changed);self::assertFalse($f->service->preflight(['native-key'=>$g],['native-key'=>$next]));$v=$f->service->present_line($g,$next);self::assertSame('review_required',$v['status']);self::assertNotNull($v['ticket']);}
	public function test_quantity_round_trip_does_not_revive_the_old_review_ticket():void{$f=new F();$g=$f->grant();$o=$f->observation($g);$v=$f->service->present_line($g,$o);self::assertTrue($f->service->invalidate_line('native-key',$f->owner));self::assertFalse($f->service->accept_line($v['ticket'],$g,$o));self::assertFalse($f->service->preflight(['native-key'=>$g],['native-key'=>$o]));}
	public function test_actual_structure_event_invalidates_pdp_before_any_receipt_exists():void{$f=new F();$p=$f->grant('');$ticket=$f->service->present_product($p,$f->observation($p));self::assertTrue($f->service->invalidate_line('never-accepted',$f->owner));$g=$f->grant();self::assertFalse($f->service->accept_after_add($ticket,$g,$f->observation($g)));self::assertCount(1,$f->rows());}
	public function test_absent_line_review_is_invalidated_even_before_it_was_accepted():void{$f=new F();$g=$f->grant();$o=$f->observation($g);$v=$f->service->present_line($g,$o);self::assertTrue($f->service->forget_line('native-key',$f->owner));self::assertFalse($f->service->accept_line($v['ticket'],$g,$o));}
	public function test_other_line_structure_does_not_invalidate_an_existing_line_generation():void{$f=new F();[$a,$oa]=$f->accepted('a');$b=$f->grant('b');$ob=$f->observation($b);$v=$f->service->present_line($a,$oa);self::assertNull($v['ticket']);$next=$f->families;$next['return_policy_v1']=D::capture(content:['summary'=>'Fresh summary'])['record'];$oa=$f->observation($a,$next);$review=$f->service->present_line($a,$oa);self::assertTrue($f->service->invalidate_line('b',$f->owner));self::assertTrue($f->service->accept_line($review['ticket'],$a,$oa));self::assertFalse($f->service->preflight(['a'=>$a,'b'=>$b],['a'=>$oa,'b'=>$ob]));}
	public function test_removed_entry_is_pruned_and_its_old_ticket_never_revives():void{$f=new F();$g=$f->grant();$o=$f->observation($g);$v=$f->service->present_line($g,$o);self::assertTrue($f->service->accept_line($v['ticket'],$g,$o));self::assertTrue($f->service->forget_line('native-key',$f->owner));$l=json_decode($f->rows()[0]['option_value'],true,32,JSON_THROW_ON_ERROR);self::assertSame([],$l['entries']);self::assertFalse($f->service->accept_line($v['ticket'],$g,$o));}
	public function test_frozen_original_and_cart_pointer_are_one_atomic_durable_handoff():void{$f=new F();[$g,$o]=$f->accepted();$p=$f->service->freeze_original('classic',1,['native-key'=>$g],['native-key'=>$o]);self::assertInstanceOf(CustomerPolicyPreparedCheckout::class,$p);self::assertSame('frozen',$p->state());self::assertNull($p->binding());self::assertSame('classic',$p->route());self::assertSame(1,$p->control_revision());self::assertCount(2,$f->rows());self::assertArrayHasKey('native-key',$p->lines());$again=$f->service->active_original($f->owner);self::assertSame($p->attempt_id(),$again->attempt_id());self::assertSame($p->original_witness(),$again->original_witness());self::assertSame(0,$f->source_reads);}
	public function test_frozen_original_cannot_be_discarded_by_structure_or_empty_cart():void{$f=new F();[$g,$o]=$f->accepted();$p=$f->service->freeze_original('classic',1,['native-key'=>$g],['native-key'=>$o]);$rows=$f->rows();self::assertFalse($f->service->invalidate_line('native-key',$f->owner));self::assertFalse($f->service->forget_line('native-key',$f->owner));self::assertFalse($f->service->retire_completed_original($f->owner,static fn():bool=>true));self::assertSame($rows,$f->rows());self::assertSame($p->attempt_id(),$f->service->active_original($f->owner)->attempt_id());}
	public function test_lost_freeze_ack_is_reconciled_as_the_same_original_without_source_read():void{$f=new F();[$g,$o]=$f->accepted();$f->configure=static function(T$t):void{$t->commit_fault='lost_ack';};$caught=null;try{$f->service->freeze_original('classic',1,['native-key'=>$g],['native-key'=>$o]);}catch(CustomerPolicyReceiptStorageException$e){$caught=$e;}self::assertInstanceOf(CustomerPolicyReceiptStorageException::class,$caught);self::assertSame('outcome_unknown',$caught->outcome);$f->configure=null;$rows=$f->rows();$p=$f->service->active_original($f->owner);self::assertSame('frozen',$p->state());self::assertSame($rows,$f->rows());self::assertSame(0,$f->source_reads);}
	public function test_freeze_without_accepted_current_review_does_not_create_original():void{$f=new F();$g=$f->grant();$o=$f->observation($g);$this->refuse(fn()=>$f->service->freeze_original('classic',1,['native-key'=>$g],['native-key'=>$o]));self::assertSame([],$f->rows());}
	public function test_incomplete_or_foreign_current_batch_refuses_before_transport():void{$f=new F();$g=$f->grant();$o=$f->observation($g);foreach([[[],[]],[['native-key'=>$g],[]],[['wrong-key'=>$g],['wrong-key'=>$o]]]as[$grants,$obs]){$this->refuse(fn()=>$f->service->present_lines($grants,$obs));}self::assertSame([],$f->transports);}
	public function test_source_family_coordinate_and_clock_must_match_the_native_observation():void{$f=new F();$g=$f->grant('native-key',['product_id'=>34]);$this->refuse(fn()=>$f->service->present_line($g,$f->observation($g)));$g=$f->grant();$this->refuse(fn()=>$f->service->present_line($g,$f->observation($g,at:'2026-10-24 12:00:01.000000')));self::assertSame([],$f->transports);}
	public function test_foreign_or_reflected_original_handle_never_becomes_an_owner():void{$f=new F();$fake=(new \ReflectionClass(CustomerPolicyPreparedCheckout::class))->newInstanceWithoutConstructor();self::assertFalse($f->service->verify_prepared($fake,(new \ReflectionClass(\CetechDeliveryEngine\Infrastructure\WordPress\OperationConnection::class))->newInstanceWithoutConstructor()));$this->refuse(fn()=>$f->service->reconcile_prepared($fake));}
	public function test_native_callbacks_run_only_before_or_after_the_dedicated_sql_owner():void{$f=new F();[$g,$o]=$f->accepted();$p=$f->service->freeze_original('classic',1,['native-key'=>$g],['native-key'=>$o]);self::assertSame('frozen',$p->state());self::assertGreaterThan(5,$f->owner_refreshes);self::assertGreaterThan(5,$f->grant_refreshes);self::assertFalse($f->pdo->inTransaction());}
	public function test_native_owner_invalidation_refuses_before_write_and_does_not_publish_a_view():void{$f=new F();$g=$f->grant();$o=$f->observation($g);$f->native_valid=false;$this->refuse(fn()=>$f->service->present_line($g,$o));self::assertSame([],$f->rows());}
	public function test_public_envelope_is_detached_customer_only_fields():void{$f=new F();$view=CartPolicyReceiptService::envelope($f->families,'ready',null);self::assertSame(['version','status','ticket','families'],array_keys($view));self::assertInstanceOf(\stdClass::class,$view['families']);foreach(get_object_vars($view['families'])as$family){self::assertSame(['disposition','customer_title','summary','full_text','exceptions'],array_keys($family));self::assertArrayNotHasKey('name',$family);self::assertArrayNotHasKey('source',$family);}self::assertStringNotContainsString('policy_uuid',json_encode($view,JSON_THROW_ON_ERROR));}
}
